                    self.MarketOrder(self.spy, -self.lot_a_shares)
                    self.lot_a_shares = 0

            if self.lot_a_shares == 0:
                if self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma:
                    target_val = 0.40 * self.Portfolio.TotalPortfolioValue
                    shares = math.floor(target_val / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)
                        self.lot_a_shares = shares

            # Slot 2 - Strategy B (AAPL)
            if self.lot_b_shares > 0:
                if aapl_rsi > 60:
                    self.MarketOrder(self.aapl, -self.lot_b_shares)
                    self.lot_b_shares = 0

            if self.lot_b_shares == 0:
                if self.aapl_red_streak >= 3:
                    if self.Portfolio.Cash >= 20000:
