from AlgorithmImports import *

class StrategySystemAlgorithm(QCAlgorithm):

    def Initialize(self):
        # Set backtest date range and initial cash
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribed tickers
        self.ticker_names = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.ticker_names:
            equity = self.AddEquity(ticker, Resolution.Daily)
            self.symbols[ticker] = equity.Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        # Strategy indicators
        self.sma_spy = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi_aapl = self.RSI(self.aapl, 14, Resolution.Daily)

        self.SetWarmUp(20, Resolution.Daily)

        # Private lots tracking
        self.lot_a = 0
        self.lot_b = 0

        # Market-state tracking
        self.prev_spy_close = None
        self.prev_spy_sma = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

    def OnData(self, slice: Slice):
        # 1. Skip rule evaluation if today's bar is missing for ANY subscribed ticker
        for sym in self.symbols.values():
            if not slice.Bars.ContainsKey(sym) or slice.Bars[sym] is None:
                return

        spy_close = slice.Bars[self.spy].Close
        aapl_close = slice.Bars[self.aapl].Close

        spy_sma = self.sma_spy.Current.Value
        rsi_aapl = self.rsi_aapl.Current.Value

        # 2. Update market-state quantities (continuous computation)
        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        spy_cross_above = False
        spy_cross_below = False
        if self.prev_spy_close is not None and self.prev_spy_sma is not None:
            if self.prev_spy_close <= self.prev_spy_sma and spy_close > spy_sma:
                spy_cross_above = True
            if self.prev_spy_close >= self.prev_spy_sma and spy_close < spy_sma:
                spy_cross_below = True

        # 3. Guard against trading before indicators are fully formed or during warm-up
        if self.IsWarmingUp or not self.sma_spy.IsReady or not self.rsi_aapl.IsReady:
            self.prev_spy_close = spy_close
            self.prev_spy_sma = spy_sma
            self.prev_aapl_close = aapl_close
            return

        # 4. Strategy A (SPY) - Sells before buys
        if self.lot_a > 0:
            if spy_cross_below:
                self.MarketOrder(self.spy, -self.lot_a)
                self.lot_a = 0
        else:
            if spy_cross_above:
                target_val = self.Portfolio.TotalPortfolioValue * 0.40
                shares = int(target_val / spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.lot_a = shares

        # 5. Strategy B (AAPL) - Sells before buys
        if self.lot_b > 0:
            if rsi_aapl > 60:
                self.MarketOrder(self.aapl, -self.lot_b)
                self.lot_b = 0
        else:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)
                        self.lot_b = shares

        # 6. Update state for cross evaluation on next bar
        self.prev_spy_close = spy_close
        self.prev_spy_sma = spy_sma
        self.prev_aapl_close = aapl_close

